// Package tdapi is the typed TDLib JSON interface Telo uses, generated by
// cmd/tdgen from td_api.tl at the pinned TDLib commit (tdapi_gen.go), plus
// the hand-written runtime in this file.
package tdapi

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"strconv"
)

//go:generate go run ../../../../cmd/tdgen -schema td_api.tl -list tdapi.list -out tdapi_gen.go

// Object is any TDLib object or function.
type Object interface {
	// TDType is the TL constructor name, the JSON "@type".
	TDType() string
}

// Transport sends one request to TDLib and returns its raw JSON answer,
// or an *Error when TDLib answers with error.
type Transport interface {
	Call(ctx context.Context, request Object) (json.RawMessage, error)
}

// Client calls TDLib functions over a transport with typed results.
type Client struct{ transport Transport }

// NewClient wraps a transport.
func NewClient(t Transport) *Client { return &Client{transport: t} }

// Call sends request and returns the raw answer.
func (c *Client) Call(ctx context.Context, request Object) (json.RawMessage, error) {
	return c.transport.Call(ctx, request)
}

// Int64 is TDLib's int64, which its JSON interface writes as a string so
// JavaScript clients keep full precision.
type Int64 int64

// MarshalJSON writes the value as a JSON string.
func (v Int64) MarshalJSON() ([]byte, error) {
	return []byte(`"` + strconv.FormatInt(int64(v), 10) + `"`), nil
}

// UnmarshalJSON accepts a JSON string or number.
func (v *Int64) UnmarshalJSON(data []byte) error {
	s := string(bytes.Trim(data, `"`))
	if s == "" || s == "null" {
		*v = 0
		return nil
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return fmt.Errorf("tdapi: int64 %s: %w", data, err)
	}
	*v = Int64(n)
	return nil
}

// marshalTyped encodes v and prepends its "@type".
func marshalTyped(tdType string, v any) ([]byte, error) {
	body, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	head := []byte(`{"@type":` + strconv.Quote(tdType))
	if len(body) <= 2 {
		return append(head, '}'), nil
	}
	return append(append(head, ','), body[1:]...), nil
}

// typeOf reads the "@type" of a raw object; null decodes to "".
func typeOf(raw json.RawMessage) (string, error) {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
		return "", nil
	}
	var head struct {
		Type string `json:"@type"`
	}
	if err := json.Unmarshal(raw, &head); err != nil {
		return "", err
	}
	return head.Type, nil
}

// Unknown is a TDLib object whose constructor this build does not generate.
type Unknown struct {
	Type string
	Raw  json.RawMessage
}

// TDType returns the constructor name.
func (u *Unknown) TDType() string { return u.Type }

// Decode decodes any generated object by its "@type"; other constructors
// return *Unknown.
func Decode(raw json.RawMessage) (Object, error) {
	t, err := typeOf(raw)
	if err != nil {
		return nil, err
	}
	if decode, ok := decoders[t]; ok {
		return decode(raw)
	}
	return &Unknown{Type: t, Raw: append(json.RawMessage(nil), raw...)}, nil
}

// TDError reports a TDLib error answer as a Go error.
func (e *Error) Error() string { return fmt.Sprintf("tdlib %d: %s", e.Code, e.Message) }

// IsError tells whether err is a TDLib error with code and, when message
// is not empty, that message.
func IsError(err error, code int32, message string) bool {
	e, ok := err.(*Error)
	return ok && e.Code == code && (message == "" || e.Message == message)
}

// Decodes tells whether this build generates the constructor named tdType.
func Decodes(tdType string) bool {
	_, ok := decoders[tdType]
	return ok
}
